INSERT INTO generation_profiles VALUES(1,'Hero Images','hero_images','Turn any product photo into a professional studio shot. Upload a single reference image and get multiple polished, magazine-ready angles, dramatic lighting, clean backgrounds, catalog-perfect composition. No studio, no photographer, no editing skills required.',1,'2026-08-19 08:05:29','2026-08-19 08:55:39',5,NULL);
INSERT INTO generation_profiles VALUES(2,'UGC Images','ugc_images','Turn any product photo into authentic, scroll-stopping content. Upload a single reference image and get natural, realistic lifestyle shots — casual settings, believable lighting, everyday moments — while keeping your product exactly accurate down to every detail. No creators, no photoshoots, no staging required.',1,'2026-08-19 08:05:29','2026-08-19 08:05:29',2,NULL);
