INSERT INTO generation_profiles VALUES(10,'Profile Cover Images','profile-cover-images','Upload a reference photo, and this system generates multiple professional cover-style image prompts featuring the exact same person in different environments — office, studio, café, home, or editorial settings. Each prompt preserves the person''s face, skin tone, hair, glasses, and build perfectly while varying the scene, pose, expression, outfit, and lighting. Ready-to-use for LinkedIn, podcast thumbnails, YouTube covers, social media, or any professional platform.',1,'2026-08-27 17:17:22','2026-08-27 17:17:35',14,NULL);
