PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE generation_profiles (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                slug TEXT NOT NULL UNIQUE,
                description TEXT,
                is_active INTEGER NOT NULL DEFAULT 1,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            , active_version_id INTEGER, owner_id TEXT);
CREATE TABLE profile_versions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                profile_id INTEGER NOT NULL,
                version_number INTEGER NOT NULL,
                system_instruction TEXT NOT NULL,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

                FOREIGN KEY (profile_id)
                    REFERENCES generation_profiles(id)
                    ON DELETE CASCADE,

                UNIQUE(profile_id, version_number)
            );
CREATE TABLE generation_jobs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                profile_id INTEGER NOT NULL,
                profile_version_id INTEGER NOT NULL,

                description TEXT,

                requested_count TEXT NOT NULL DEFAULT 'auto',

                status TEXT NOT NULL DEFAULT 'pending',

                system_instruction_snapshot TEXT NOT NULL,

                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, planner_model TEXT, planner_raw_output TEXT, planner_error TEXT, planned_at TEXT, normalizer_model TEXT, structured_output_json TEXT, normalizer_error TEXT, normalized_at TEXT, planner_provider TEXT, is_favorite INTEGER
                NOT NULL DEFAULT 0, aspect_ratio TEXT, planner_provider_snapshot TEXT, planner_model_snapshot TEXT, planner_reasoning_snapshot TEXT, image_provider_snapshot TEXT, image_model_snapshot TEXT, image_quality_snapshot TEXT, image_size_snapshot TEXT, image_output_format_snapshot TEXT, batch_concurrency_snapshot INTEGER, owner_id TEXT, planner_tier_snapshot TEXT, image_tier_snapshot TEXT,

                FOREIGN KEY (profile_id)
                    REFERENCES generation_profiles(id),

                FOREIGN KEY (profile_version_id)
                    REFERENCES profile_versions(id)
            );
CREATE TABLE reference_images (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                job_id INTEGER NOT NULL,

                position INTEGER NOT NULL,

                original_filename TEXT NOT NULL,
                stored_filename TEXT NOT NULL,
                file_path TEXT NOT NULL,

                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

                FOREIGN KEY (job_id)
                    REFERENCES generation_jobs(id)
                    ON DELETE CASCADE
            );
CREATE TABLE generated_prompts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                job_id INTEGER NOT NULL,

                position INTEGER NOT NULL,

                title TEXT,
                prompt_text TEXT NOT NULL,

                metadata_json TEXT,

                status TEXT NOT NULL DEFAULT 'pending',

                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

                FOREIGN KEY (job_id)
                    REFERENCES generation_jobs(id)
                    ON DELETE CASCADE
            );
CREATE TABLE generated_images (
                id INTEGER PRIMARY KEY AUTOINCREMENT,

                job_id INTEGER NOT NULL,
                prompt_id INTEGER,

                provider TEXT,

                file_path TEXT,

                status TEXT NOT NULL DEFAULT 'pending',

                error_message TEXT,

                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, generation_note TEXT, is_favorite INTEGER
                NOT NULL DEFAULT 0,

                FOREIGN KEY (job_id)
                    REFERENCES generation_jobs(id)
                    ON DELETE CASCADE,

                FOREIGN KEY (prompt_id)
                    REFERENCES generated_prompts(id)
                    ON DELETE SET NULL
            );
CREATE TABLE provider_credentials (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                owner_key TEXT NOT NULL,
                provider TEXT NOT NULL,
                encrypted_key TEXT NOT NULL,
                key_suffix TEXT NOT NULL,
                created_at TEXT NOT NULL
                    DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT NOT NULL
                    DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(owner_key, provider)
            );
CREATE TABLE app_settings (
                    owner_id TEXT NOT NULL,
                    key TEXT NOT NULL,
                    value TEXT NOT NULL,
                    updated_at TEXT NOT NULL
                        DEFAULT CURRENT_TIMESTAMP,
                    PRIMARY KEY (
                        owner_id,
                        key
                    )
                );
CREATE TABLE app_users (
                user_id TEXT PRIMARY KEY,
                email TEXT,
                display_name TEXT,
                role TEXT NOT NULL
                    DEFAULT 'user',
                status TEXT NOT NULL
                    DEFAULT 'active',
                created_at TEXT NOT NULL
                    DEFAULT CURRENT_TIMESTAMP,
                last_seen_at TEXT NOT NULL
                    DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE model_registry (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                provider TEXT NOT NULL,
                capability TEXT NOT NULL,
                tier TEXT NOT NULL,
                model_id TEXT NOT NULL,
                display_name TEXT NOT NULL,
                note TEXT,
                config_json TEXT NOT NULL DEFAULT '{}',
                enabled INTEGER NOT NULL DEFAULT 1,
                sort_order INTEGER NOT NULL DEFAULT 100,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                UNIQUE (
                    provider,
                    capability,
                    tier
                )
            );
CREATE TABLE feature_flags (
                key TEXT PRIMARY KEY,
                enabled INTEGER NOT NULL DEFAULT 0,
                description TEXT,
                updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE usage_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT NOT NULL,
                event_type TEXT NOT NULL,
                job_id INTEGER,
                provider TEXT,
                model TEXT,
                quantity INTEGER NOT NULL DEFAULT 1,
                metadata_json TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE model_registry_meta (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            );
CREATE TABLE managed_workflows (
                    profile_id INTEGER PRIMARY KEY,
                    workflow_type TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'draft',
                    sort_order INTEGER NOT NULL DEFAULT 100,
                    is_system INTEGER NOT NULL DEFAULT 0,
                    created_by TEXT,
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

                    FOREIGN KEY (
                        profile_id
                    )
                        REFERENCES generation_profiles(id)
                        ON DELETE CASCADE
                );
CREATE TABLE managed_workflow_versions (
                    profile_version_id INTEGER PRIMARY KEY,
                    encrypted_instruction TEXT,
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

                    FOREIGN KEY (
                        profile_version_id
                    )
                        REFERENCES profile_versions(id)
                        ON DELETE CASCADE
                );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_profile_versions_profile

            ON profile_versions(profile_id)
            ;
CREATE INDEX idx_generation_jobs_profile

            ON generation_jobs(profile_id)
            ;
CREATE INDEX idx_generation_jobs_version

            ON generation_jobs(profile_version_id)
            ;
CREATE INDEX idx_generated_prompts_job
            ON generated_prompts(job_id)
            ;
CREATE INDEX idx_generation_jobs_favorite
            ON generation_jobs(is_favorite)
            ;
CREATE INDEX idx_generated_images_favorite
            ON generated_images(is_favorite)
            ;
CREATE INDEX idx_generation_profiles_owner
            ON generation_profiles(
                owner_id
            )
            ;
CREATE INDEX idx_generation_jobs_owner
            ON generation_jobs(
                owner_id
            )
            ;
CREATE INDEX idx_app_users_email
            ON app_users(email)
            ;
CREATE INDEX idx_usage_events_user
            ON usage_events(
                user_id,
                created_at
            )
            ;
CREATE INDEX idx_managed_workflows_status
                ON managed_workflows(
                    status,
                    sort_order,
                    profile_id
                )
                ;
COMMIT;
